	L["This is a custom button.  Please ask the addon author to use the standard LibDBIcon library instead."] = "Dies ist eine benutzerdefinierte Schaltfläche.  Bitte den Autor des Addons, stattdessen die Standardbibliothek LibDBIcon zu verwenden."
	L["This is a list of available addon button names.  You can use this list to copy and paste button names that you want into the editor.|n|nThis listing is automatically generated and cannot be edited."] = "Dies ist eine Liste der verfügbaren Namen von Addon-Schaltflächen.  Du kannst diese Liste verwenden, um die gewünschten Schaltflächennamen zu kopieren und in den Editor einzufügen.|n|nDiese Liste wird automatisch erstellt und kann nicht bearbeitet werden."
