	L["Click to disable Titan Panel frame adjustment.  Your UI will be reloaded."] = "Haz clic para desactivar el ajuste de marcos de Titan Panel.  Tu IU se recargará."
	L["Click to mute every sound file in the game.  This ends the current search and sounds stay muted when the panel is closed."] = "Haz clic para silenciar todos los archivos de sonido del juego.  Esto finaliza la búsqueda actual y los sonidos permanecen silenciados al cerrar el panel."
	L["Click to mute every sound in the game."] = "Haz clic para silenciar todos los sonidos del juego."
