	L["Click Play to check it."] = "Cliquez sur Jouer pour le vérifier."
	L["Click to close the currently active flight progress bar."] = "Cliquez pour fermer la barre de progression de vol actuellement active."
	L["Click to configure the settings for this option."] = "Cliquez pour configurer les paramètres de cette option."
	L["Click to disable Titan Panel frame adjustment.  Your UI will be reloaded."] = "Cliquez pour désactiver l'ajustement des cadres de Titan Panel.  Votre interface sera rechargée."
	L["Click to mute every sound file in the game.  This ends the current search and sounds stay muted when the panel is closed."] = "Cliquez pour rendre muets tous les fichiers sonores du jeu.  Cela met fin à la recherche en cours et les sons restent muets à la fermeture du panneau."
	L["Click to mute every sound in the game."] = "Cliquez pour rendre muets tous les sons du jeu."
	L["Click to mute sounds in the list."] = "Cliquez pour couper les sons dans la liste."
	L["Click to play the sound file that was found."] = "Cliquez pour jouer le fichier sonore trouvé."
	L["Click to reset the settings on this page."] = "Cliquez pour réinitialiser les paramètres de cette page."
	L["Click to restart the sound system.  Use this after each step if you are looking for music or ambience (sounds that are already playing are not muted until the sound system is restarted)."] = "Cliquez pour redémarrer le système audio.  Utilisez-le après chaque étape si vous cherchez une musique ou une ambiance (les sons déjà en cours de lecture ne sont rendus muets qu'au redémarrage du système audio)."
	L["Click to return to the main menu."] = "Cliquez pour revenir au menu principal."
	L["Click to set the sound file limit.  Use the mousewheel on the editbox along with the step buttons below to adjust the sound limit.  Acceptable range is from 1 to 9000000.  Sound files higher than this limit will be muted."] = "Cliquez pour définir la limite des fichiers sonores.  Utilisez la molette de la souris sur la zone de saisie ainsi que les boutons de pas ci-dessous pour ajuster la limite.  La plage acceptée va de 1 à 9000000.  Les fichiers sonores au-delà de cette limite seront rendus muets."
	L["Click to start a new search."] = "Cliquez pour lancer une nouvelle recherche."
	L["Click to toggle the addon buttons editor."] = "Cliquez pour basculer l'éditeur des boutons d'add-on."
	L["Click to toggle the frame alignment grid."] = "Cliquez pour basculer la grille d'alignement du cadre."
	L["Click to toggle the sound finder."] = "Cliquez pour afficher ou masquer le chercheur de sons."
	L["Click to undo your last heard it or silent answer."] = "Cliquez pour annuler votre dernière réponse 'Entendu' ou 'Silence'."
	L["Click to unmute every sound file in the game.  This ends the current search and also unmutes sounds muted by Leatrix Plus or other addons (reload your UI to restore them)."] = "Cliquez pour réactiver tous les fichiers sonores du jeu.  Cela met fin à la recherche en cours et réactive également les sons rendus muets par Leatrix Plus ou d'autres addons (rechargez votre interface pour les restaurer)."
	L["Click to unmute every sound in the game."] = "Cliquez pour réactiver tous les sons du jeu."
	L["Click to unmute sounds in the list."] = "Cliquez pour activer le son dans la liste."
