	L["Dead Blanchy alert active.  Spawn point has been pinned to the Revendreth map.  An alert will sound 20 times when Blanchy emotes nearby."] = "Alerte pour Feu Blanchette active.  Le point d'apparition a été épinglé sur la carte de Revendreth.  Une alerte retentira 20 fois quand Blanchette fera une émote à proximité."
