	L["The following list shows option label, setting name and currently saved value.  Enable |cffffffffIncrease chat history|r (chat) and |cffffffffRecent chat window|r (chat) to make it easier."] = "La liste suivante affiche le libellé de l'option, le nom du paramètre et la valeur actuellement enregistrée.  Activez |cffffffffL'historique|r (discussion) et |cffffffffDiscussion récente|r (discussion) pour vous faciliter la tâche."
