	L["Dead Blanchy"] = "Defunta Blanchy"
	L["Dead Blanchy alert active.  Spawn point has been pinned to the Revendreth map.  An alert will sound 20 times when Blanchy emotes nearby."] = "Avviso per Defunta Blanchy attivo.  Il punto di comparsa è stato segnato sulla mappa di Revendreth.  Un avviso suonerà 20 volte quando Blanchy eseguirà un'emote nelle vicinanze."
	L["Dead Blanchy alert disabled."] = "Avviso per Defunta Blanchy disattivato."
