	L["Desolace"] = "Desolanda"
	L["Devotion Aura"] = "Aura della Devozione"
	L["Dire Maul"] = "Maglio Infausto"
	L["Disable chat fade"] = "Disattiva la dissolvenza della chat"
	L["Disable drunken haze"] = "Disattiva l'offuscamento dell'ubriachezza"
	L["Disable loot warnings"] = "Disattiva gli avvisi del bottino"
	L["Disable screen effects"] = "Disattiva gli effetti dello schermo"
	L["Disable sticky chat"] = "Disattiva la chat persistente"
	L["Drag the frame overlay to position the frame."] = "Trascina il riquadro sovrapposto per posizionare il riquadro."
	L["Drag the frame overlay with the left button to position it freely or with the right button to position it using snap-to-grid."] = "Trascina il riquadro sovrapposto con il tasto sinistro per posizionarlo liberamente o con il tasto destro per posizionarlo allineandolo alla griglia."
	L["Drag to set the character model zoom speed."] = "Trascina per impostare la velocità dello zoom del modello del personaggio."
	L["Drag to set the cluster scale."] = "Trascina per impostare la scala del gruppo."
	L["Drag to set the cursor X offset."] = "Trascina per impostare lo spostamento X del puntatore."
	L["Drag to set the cursor Y offset."] = "Trascina per impostare lo spostamento Y del puntatore."
	L["Drag to set the delay between looting items.|n|nLower is faster but may not always give the best results.|n|nIt's recommended that you leave this setting at 0.3 but feel free to try lower values if you wish."] = "Trascina per impostare il ritardo tra la raccolta degli oggetti.|n|nUn valore più basso è più veloce ma potrebbe non dare sempre i risultati migliori.|n|nSi consiglia di lasciare questa impostazione a 0.3, ma se vuoi puoi provare valori più bassi."
	L["Drag to set the density of weather effects."] = "Trascina per impostare la densità degli effetti meteorologici."
	L["Drag to set the flight progress bar scale."] = "Trascina per impostare la scala della barra di avanzamento del volo."
	L["Drag to set the flight progress bar width."] = "Trascina per impostare la larghezza della barra di avanzamento del volo."
	L["Drag to set the font size of quest text."] = "Trascina per impostare la dimensione del carattere del testo delle missioni."
	L["Drag to set the number of milliseconds before you are automatically released.|n|nYou can hold down shift as the timer is ending to cancel the automatic release."] = "Trascina per impostare il numero di millisecondi prima che il tuo spirito venga liberato automaticamente.|n|nPuoi tenere premuto MAIUSC mentre il timer sta per scadere per annullare la liberazione automatica."
	L["Drag to set the scale of the flight map."] = "Trascina per impostare la scala della mappa dei voli."
	L["Drag to set the scale of the Leatrix Plus panel."] = "Trascina per impostare la scala del pannello di Leatrix Plus."
	L["Drag to set the size of the bottom border."] = "Trascina per impostare la dimensione del bordo inferiore."
	L["Drag to set the size of the icons."] = "Trascina per impostare la dimensione delle icone."
	L["Drag to set the size of the left border."] = "Trascina per impostare la dimensione del bordo sinistro."
	L["Drag to set the size of the right border."] = "Trascina per impostare la dimensione del bordo destro."
	L["Drag to set the size of the top border."] = "Trascina per impostare la dimensione del bordo superiore."
	L["Drag to set the square minimap border width."] = "Trascina per impostare la larghezza del bordo della minimappa quadrata."
	L["Drag to set the tooltip scale."] = "Trascina per impostare la scala dei tooltip."
	L["Drag to set the transparency of the borders."] = "Trascina per impostare la trasparenza dei bordi."
	L["Drag to set the transparency of the Leatrix Plus panel."] = "Trascina per impostare la trasparenza del pannello di Leatrix Plus."
	L["Drag to set the widget top scale."] = "Trascina per impostare la scala del widget superiore."
	L["Drag to size"] = "Trascina per ridimensionare"
