	L["Enter item IDs separated by commas.  Item IDs can be found in item tooltips while this panel is showing.|n|nJunk items entered here will not be sold automatically.|n|nWhite items entered here will be sold automatically.|n|nThe editbox tooltip will show you more information about the items you have entered."] = "Inserisci gli ID degli oggetti separati da virgole.  Gli ID degli oggetti sono visibili nei tooltip degli oggetti mentre questo pannello è aperto.|n|nLe cianfrusaglie inserite qui non verranno vendute automaticamente.|n|nGli oggetti bianchi inseriti qui verranno venduti automaticamente.|n|nIl tooltip della casella di testo mostra maggiori informazioni sugli oggetti inseriti."
	L["Enter sound file IDs separated by comma then click the Mute button.|n|nIf you wish, you can enter a brief note for each file ID but do not include numbers in your notes.|n|nFor example, you can enter 'DevAura 569679, RetAura 568744' to mute the Devotion Aura and Retribution Aura spells.|n|nUse Leatrix Sounds to find, test and play sound file IDs."] = "Inserisci gli ID dei file audio separati da virgole, quindi clicca sul pulsante Silenzia.|n|nSe vuoi, puoi inserire una breve nota per ogni ID di file, ma non includere numeri nelle note.|n|nAd esempio, puoi inserire 'DevAura 569679, RetAura 568744' per silenziare gli incantesimi Aura della Devozione e Aura del Castigo.|n|nUsa Leatrix Sounds per trovare, provare e riprodurre gli ID dei file audio."
	L["enter zone or track name"] = "inserisci il nome della zona o della traccia"
