	L["Hide alerts"] = "Nascondi gli avvisi"
	L["Hide boss banner"] = "Nascondi lo stendardo del boss"
	L["Hide chat buttons"] = "Nascondi i pulsanti della chat"
	L["Hide clean-up buttons"] = "Nascondi i pulsanti di riordino"
	L["Hide error messages"] = "Nascondi i messaggi di errore"
	L["Hide event toasts"] = "Nascondi le notifiche degli eventi"
	L["Hide keybind text"] = "Nascondi il testo delle assegnazioni dei tasti"
	L["Hide macro text"] = "Nascondi il testo delle macro"
	L["Hide portrait numbers"] = "Nascondi i numeri sul ritratto"
	L["Hide rested sleep"] = "Nascondi il sonno del riposo"
	L["Hide social button"] = "Nascondi il pulsante social"
	L["Hide stance bar"] = "Nascondi la barra della postura"
	L["Hide the combat log"] = "Nascondi il registro di combattimento"
	L["Hide the health bar"] = "Nascondi la barra della salute"
