	L["This is a custom button.  Please ask the addon author to use the standard LibDBIcon library instead."] = "Questo è un pulsante personalizzato.  Chiedi all'autore dell'addon di usare invece la libreria standard LibDBIcon."
	L["This is a list of available addon button names.  You can use this list to copy and paste button names that you want into the editor.|n|nThis listing is automatically generated and cannot be edited."] = "Questa è una lista dei nomi dei pulsanti degli addon disponibili.  Puoi usare questa lista per copiare e incollare nell'editor i nomi dei pulsanti che desideri.|n|nQuesta lista viene generata automaticamente e non può essere modificata."
