	L["Dead Blanchy"] = "Brancurinha Defunta"
	L["Dead Blanchy alert active.  Spawn point has been pinned to the Revendreth map.  An alert will sound 20 times when Blanchy emotes nearby."] = "Alerta de Brancurinha Defunta ativo.  O ponto de surgimento foi marcado no mapa de Revendreth.  Um alerta soará 20 vezes quando Brancurinha fizer uma expressão por perto."
	L["Dead Blanchy alert disabled."] = "Alerta de Brancurinha Defunta desativado."
