	L["This is a list of available addon button names.  You can use this list to copy and paste button names that you want into the editor.|n|nThis listing is automatically generated and cannot be edited."] = "Esta é uma lista dos nomes de botões de addons disponíveis.  Você pode usar esta lista para copiar e colar no editor os nomes dos botões que desejar.|n|nEsta lista é gerada automaticamente e não pode ser editada."
