	L["The link cannot be copied right now"] = "Ссылку сейчас нельзя скопировать"
	L["The saved flight time is"] = "Сохраненное время полета:"
	L["The sound finder lets you find the file ID of a sound that is playing in game.|n|nPlay the sound you want to find and click the start button.  Each step mutes half of the remaining sound files.  Click the heard button if you can still hear the sound or the silent button if you cannot.|n|nFor sound effects (such as an ability or emote), play the sound again after each step.  For music or ambience, click the sound system restart button after each step.|n|nWhen the sound file is found, its ID is shown in the editbox on the right so that you can copy it."] = "Поиск звуков позволяет найти ID файла звука, который воспроизводится в игре.|n|nВоспроизведите нужный звук и нажмите кнопку запуска.  На каждом шаге заглушается половина оставшихся звуковых файлов.  Нажмите кнопку 'Слышно', если вы все еще слышите звук, или кнопку 'Тихо', если нет.|n|nДля звуковых эффектов (например, способности или эмоции) воспроизводите звук заново после каждого шага.  Для музыки или фоновых звуков после каждого шага нажимайте кнопку перезапуска звуковой системы.|n|nКогда звуковой файл будет найден, его ID появится в поле ввода справа, чтобы его можно было скопировать."
