	L["This is a list of available addon button names.  You can use this list to copy and paste button names that you want into the editor.|n|nThis listing is automatically generated and cannot be edited."] = "Это список доступных названий кнопок аддонов.  Вы можете использовать его, чтобы скопировать и вставить в редактор нужные названия кнопок.|n|nЭтот список создается автоматически и не может быть изменен."
