	L["Click to mute every sound file in the game.  This ends the current search and sounds stay muted when the panel is closed."] = "게임의 모든 사운드 파일을 음소거하려면 클릭하세요.  현재 검색이 종료되며 창을 닫아도 소리는 음소거된 상태로 유지됩니다."
	L["Click to mute every sound in the game."] = "게임의 모든 소리를 음소거하려면 클릭하세요."
	L["Click to mute sounds in the list."] = "목록에서 소리를 음소거하려면 클릭하세요."
	L["Click to play the sound file that was found."] = "찾은 사운드 파일을 재생하려면 클릭하세요."
	L["Click to reset the settings on this page."] = "이 페이지를 재설정 하려면 클릭합니다."
	L["Click to restart the sound system.  Use this after each step if you are looking for music or ambience (sounds that are already playing are not muted until the sound system is restarted)."] = "사운드 시스템을 재시작하려면 클릭하세요.  음악이나 주변 소리를 찾는 경우 각 단계 후에 사용하세요 (이미 재생 중인 소리는 사운드 시스템을 재시작해야 음소거됩니다)."
	L["Click to return to the main menu."] = "메인 메뉴로 돌아가려면 클릭하세요."
	L["Click to set the sound file limit.  Use the mousewheel on the editbox along with the step buttons below to adjust the sound limit.  Acceptable range is from 1 to 9000000.  Sound files higher than this limit will be muted."] = "사운드 파일 제한을 설정하려면 클릭하세요.  입력창에서 마우스 휠과 아래의 단계 버튼을 사용하여 제한을 조절할 수 있습니다.  허용 범위는 1부터 9000000까지입니다.  이 제한보다 높은 사운드 파일은 음소거됩니다."
	L["Click to start a new search."] = "새 검색을 시작하려면 클릭하세요."
