	L["Click to toggle the sound finder."] = "소리 찾기를 열거나 닫으려면 클릭하세요."
	L["Click to undo your last heard it or silent answer."] = "마지막 '들림' 또는 '안 들림' 응답을 취소하려면 클릭하세요."
	L["Click to unmute every sound file in the game.  This ends the current search and also unmutes sounds muted by Leatrix Plus or other addons (reload your UI to restore them)."] = "게임의 모든 사운드 파일의 음소거를 해제하려면 클릭하세요.  현재 검색이 종료되며, Leatrix Plus나 다른 애드온이 음소거한 소리도 음소거가 해제됩니다 (복원하려면 UI를 재시작하세요)."
	L["Click to unmute every sound in the game."] = "게임의 모든 소리의 음소거를 해제하려면 클릭하세요."
