	L["Drag to set the delay between looting items.|n|nLower is faster but may not always give the best results.|n|nIt's recommended that you leave this setting at 0.3 but feel free to try lower values if you wish."] = "드래그하여 아이템 획득 간 지연 시간을 설정하세요.|n|n낮을수록 빠르지만 항상 최상의 결과를 보장하지는 않습니다.|n|n이 설정을 0.3으로 유지하는 것이 권장되나, 원한다면 더 낮은 값을 시도해 보셔도 됩니다."
	L["Drag to set the density of weather effects."] = "드래그하여 날씨 효과 밀도를 설정하세요."
	L["Drag to set the flight progress bar scale."] = "드래그하여 비행 진행률 바의 크기를 설정하세요."
	L["Drag to set the flight progress bar width."] = "드래그하여 비행 진행률 바의 너비를 설정하세요."
	L["Drag to set the font size of quest text."] = "드래그하여 퀘스트 텍스트 글꼴 크기를 설정하세요."
	L["Drag to set the number of milliseconds before you are automatically released.|n|nYou can hold down shift as the timer is ending to cancel the automatic release."] = "드래그하여 자동 부활되기까지의 밀리초 수를 설정하세요.|n|n타이머 종료 시 shift 키를 누르고 있으면 자동 부활을 취소할 수 있습니다."
	L["Drag to set the scale of the flight map."] = "드래그하여 비행 지도 축척을 설정하세요."
	L["Drag to set the scale of the Leatrix Plus panel."] = "드래그하여 Leatrix Plus 설정창 크기를 설정하세요."
	L["Drag to set the size of the bottom border."] = "드래그하여 아래쪽 테두리의 크기를 설정하세요."
	L["Drag to set the size of the icons."] = "드래그하여 아이콘의 크기를 설정하세요."
	L["Drag to set the size of the left border."] = "드래그하여 왼쪽 테두리의 크기를 설정하세요."
	L["Drag to set the size of the right border."] = "드래그하여 오른쪽 테두리의 크기를 설정하세요."
	L["Drag to set the size of the top border."] = "드래그하여 상단 테두리의 크기를 설정하세요."
	L["Drag to set the square minimap border width."] = "드래그하여 사각형 미니맵 테두리 너비를 설정하세요."
	L["Drag to set the tooltip scale."] = "드래그하여 툴팁 크기를 설정하세요."
	L["Drag to set the transparency of the borders."] = "드래그하여  테두리의 투명도를 설정하세요."
	L["Drag to set the transparency of the Leatrix Plus panel."] = "드래그하여 Leatrix Plus 설정창 투명도를 설정하세요."
	L["Drag to set the widget top scale."] = "드래그하여 상단 위젯 크기를 설정합니다."
