	L["The default delay setting is 0.3.  Lower is faster but may not always give the best results.  It's recommended that you leave this setting at 0.3."] = "기본 지연 설정값은 0.3입니다. 낮출수록 속도는 빨라지지만 항상 최상의 결과를 보장하지는 않습니다. 이 설정값을 0.3으로 유지하는 것이 좋습니다."
	L["The following list shows option label, setting name and currently saved value.  Enable |cffffffffIncrease chat history|r (chat) and |cffffffffRecent chat window|r (chat) to make it easier."] = "다음 목록은 옵션 이름, 설정 이름 및 현재 저장된 값을 보여줍니다.  더 쉽게 보려면 |cffffffff채팅 기록 증가|r (대화) 및 |cffffffff최근 채팅|r (대화)를 활성화하세요."
	L["The link cannot be copied right now"] = "지금은 링크를 복사할 수 없습니다"
	L["The saved flight time is"] = "저장된 비행 시간:"
	L["The sound finder lets you find the file ID of a sound that is playing in game.|n|nPlay the sound you want to find and click the start button.  Each step mutes half of the remaining sound files.  Click the heard button if you can still hear the sound or the silent button if you cannot.|n|nFor sound effects (such as an ability or emote), play the sound again after each step.  For music or ambience, click the sound system restart button after each step.|n|nWhen the sound file is found, its ID is shown in the editbox on the right so that you can copy it."] = "소리 찾기를 사용하면 게임에서 재생 중인 소리의 파일 ID를 찾을 수 있습니다.|n|n찾고 싶은 소리를 재생한 후 시작 버튼을 클릭하세요.  각 단계마다 남은 사운드 파일의 절반이 음소거됩니다.  소리가 아직 들리면 '들림' 버튼을, 들리지 않으면 '안 들림' 버튼을 클릭하세요.|n|n효과음(기술이나 감정 표현 등)의 경우 각 단계 후에 소리를 다시 재생하세요.  음악이나 주변 소리의 경우 각 단계 후에 사운드 시스템 재시작 버튼을 클릭하세요.|n|n사운드 파일을 찾으면 오른쪽 입력창에 ID가 표시되어 복사할 수 있습니다."
	L["The summon from"] = "당신을 소환하는 자"
	L["Their gear could not be read."] = "장비를 읽을 수 없습니다."
	L["Then click Start."] = "그런 다음 시작을 클릭하세요."
	L["Thirty seconds"] = "30초"
	L["This flight is not in the database yet."] = "이 비행은 아직 데이터베이스에 없습니다."
	L["This is a custom button.  Please ask the addon author to use the standard LibDBIcon library instead."] = "사용자 지정 버튼입니다.  애드온 제작자에게 표준 LibDBIcon 라이브러리를 사용하도록 요청하세요."
	L["This is a list of available addon button names.  You can use this list to copy and paste button names that you want into the editor.|n|nThis listing is automatically generated and cannot be edited."] = "다음은 사용 가능한 애드온 버튼 이름 목록입니다. 이 목록을 참고하여 원하는 버튼 이름을 복사하여 편집기에 붙여넣을 수 있습니다.|n|n이 목록은 자동으로 생성된 것으로, 편집할 수 없습니다."
