	L["Click Play to check it."] = "點擊播放進行確認。"
	L["Click to close the currently active flight progress bar."] = "按一下可關閉目前活動的飛行進度條。"
	L["Click to configure the settings for this option."] = "點擊進行額外的選項設置"
	L["Click to disable Titan Panel frame adjustment.  Your UI will be reloaded."] = "點擊停用Titan Panel的框架調整功能。  你的介面將會重載。"
	L["Click to mute every sound file in the game.  This ends the current search and sounds stay muted when the panel is closed."] = "點擊靜音遊戲中的所有聲音檔案。  這會結束目前的搜尋，並且關閉面板後聲音仍保持靜音。"
	L["Click to mute every sound in the game."] = "點擊靜音遊戲中的所有聲音。"
	L["Click to mute sounds in the list."] = "單擊可使列表中的聲音靜音。"
	L["Click to play the sound file that was found."] = "點擊播放找到的聲音檔案。"
	L["Click to reset the settings on this page."] = "點擊重置此頁面的設置。"
	L["Click to restart the sound system.  Use this after each step if you are looking for music or ambience (sounds that are already playing are not muted until the sound system is restarted)."] = "點擊重啟聲音系統。  如果你在尋找音樂或環境音，請在每一步後使用此功能(已經在播放的聲音要等聲音系統重啟後才會被靜音)。"
	L["Click to return to the main menu."] = "點擊返回到主選單"
	L["Click to set the sound file limit.  Use the mousewheel on the editbox along with the step buttons below to adjust the sound limit.  Acceptable range is from 1 to 9000000.  Sound files higher than this limit will be muted."] = "點擊設定聲音檔案限制。  在輸入框上使用滑鼠滾輪並配合下方的步進按鈕來調整限制。  可接受範圍為1至9000000。  高於此限制的聲音檔案將被靜音。"
	L["Click to start a new search."] = "點擊開始新的搜尋。"
	L["Click to toggle the addon buttons editor."] = "點擊以切換插件按鈕編輯器。"
	L["Click to toggle the frame alignment grid."] = "點擊切換框架對齊網格。"
	L["Click to toggle the sound finder."] = "點擊開關聲音尋找器。"
	L["Click to undo your last heard it or silent answer."] = "點擊撤銷你上一次的'聽到了'或'靜音'回答。"
	L["Click to unmute every sound file in the game.  This ends the current search and also unmutes sounds muted by Leatrix Plus or other addons (reload your UI to restore them)."] = "點擊取消遊戲中所有聲音檔案的靜音。  這會結束目前的搜尋，同時也會取消由Leatrix Plus或其他插件靜音的聲音(重載介面即可恢復)。"
	L["Click to unmute every sound in the game."] = "點擊取消遊戲中所有聲音的靜音。"
	L["Click to unmute sounds in the list."] = "單擊以取消列表中的靜音。"
