	L["The default delay setting is 0.3.  Lower is faster but may not always give the best results.  It's recommended that you leave this setting at 0.3."] = "預設延遲設置為 0.3。越低越快，但不一定總能提供最佳結果。建議您將此設置保留為 0.3。"
	L["The following list shows option label, setting name and currently saved value.  Enable |cffffffffIncrease chat history|r (chat) and |cffffffffRecent chat window|r (chat) to make it easier."] = "以下列表顯示選項標籤、設定名稱和目前儲存的值。  啟用|cffffffff增加聊天歷史記錄|r(聊天)和|cffffffff最近聊天視窗|r(聊天)會更方便查看。"
