	L["The saved flight time is"] = "已儲存的飛行時間為"
	L["The sound finder lets you find the file ID of a sound that is playing in game.|n|nPlay the sound you want to find and click the start button.  Each step mutes half of the remaining sound files.  Click the heard button if you can still hear the sound or the silent button if you cannot.|n|nFor sound effects (such as an ability or emote), play the sound again after each step.  For music or ambience, click the sound system restart button after each step.|n|nWhen the sound file is found, its ID is shown in the editbox on the right so that you can copy it."] = "聲音尋找器可以幫你找到遊戲中正在播放的聲音的檔案ID。|n|n播放你想尋找的聲音，然後點擊開始按鈕。  每一步都會靜音剩餘聲音檔案的一半。  如果你仍能聽到聲音，請點擊'聽到了'按鈕，否則請點擊'靜音'按鈕。|n|n對於音效(如技能或表情動作)，請在每一步後重新播放該聲音。  對於音樂或環境音，請在每一步後點擊重啟聲音系統按鈕。|n|n找到聲音檔案後，其ID會顯示在右側的輸入框中，以便你複製。"
